import unittest
from candidate import add

class TestAddition(unittest.TestCase):
    def test_add_two_positive_numbers(self):
        self.assertEqual(add(2, 3), 5)

    def test_add_two_negative_numbers(self):
        self.assertEqual(add(-2, -3), -5)

    def test_add_mixed_numbers(self):
        self.assertEqual(add(-2, 3), 1)

    def test_add_with_zero(self):
        self.assertEqual(add(0, 5), 5)

    def test_add_with_non_integer_input(self):
        with self.assertRaises(TypeError):
            add(2.5, 3)

    def test_add_with_non_numeric_input(self):
        with self.assertRaises(TypeError):
            add('2', 3)

    def test_add_with_single_argument(self):
        with self.assertRaises(TypeError):
            add(2)

    def test_add_with_no_arguments(self):
        with self.assertRaises(TypeError):
            add()

    def test_add_with_none_value(self):
        with self.assertRaises(TypeError):
            add(2, None)

if __name__ == '__main__':
    unittest.main()
